/// Playing a sound, behind a seam.
///
/// The rest of the app talks to [SoundOutput] and never to `audioplayers`, for
/// the same reason the device layer talks to `Transport`: the cue logic is then
/// testable with no audio hardware, and a platform where playback does not work
/// degrades to silence instead of throwing.
///
/// Every tone ships in `assets/sounds/`, generated by `tools/make_sounds.py`.
/// Nothing is fetched, so the sounds work on a phone in flight mode.
library;

import 'dart:async';
import 'dart:typed_data';

import 'package:audioplayers/audioplayers.dart';

/// The four things the app has to say out loud.
enum FfSound {
  /// A block is beginning. Two notes, rising.
  blockStart('sounds/block_start.wav'),

  /// A block is done and the next one is coming. Three notes, settling.
  blockEnd('sounds/block_end.wav'),

  /// One of the last three seconds. Quiet and short.
  tick('sounds/tick.wav'),

  /// The run is over and you may not be looking at the phone.
  alarm('sounds/alarm.wav');

  const FfSound(this.asset);

  /// Relative to `assets/` — `audioplayers` adds that prefix itself.
  final String asset;
}

abstract interface class SoundOutput {
  Future<void> play(FfSound sound);

  /// Stops the alarm. Short cues are left to finish — they are shorter than
  /// the gesture that would stop them.
  Future<void> stopAlarm();

  /// Plays a generated WAV: the virtual bot's buzzer. A new one replaces
  /// whatever the buzzer was playing, as `tone()` does on the Arduino.
  Future<void> playWave(Uint8List wav);

  Future<void> stopWave();

  /// A short generated effect: a click or a game sound. On its own player,
  /// so it never cuts off the music.
  Future<void> playFx(Uint8List wav);

  /// A generated alarm tone, on the alarm player: [stopAlarm] stops it.
  Future<void> playAlarmWave(Uint8List wav);

  Future<void> dispose();
}

/// The real one.
class AudioSoundOutput implements SoundOutput {
  AudioSoundOutput();

  /// Two players, on purpose: stopping a five-second alarm must not cut off a
  /// tick, and a tick landing must not restart the alarm.
  final AudioPlayer _cues = AudioPlayer(playerId: 'ff_cues')
    ..setPlayerMode(PlayerMode.lowLatency)
    ..setReleaseMode(ReleaseMode.stop);
  final AudioPlayer _alarm = AudioPlayer(playerId: 'ff_alarm')
    ..setReleaseMode(ReleaseMode.stop);

  /// The bot's buzzer, separate so a melody never cuts off a session cue.
  final AudioPlayer _buzzer = AudioPlayer(playerId: 'ff_buzzer')
    ..setReleaseMode(ReleaseMode.stop);

  /// Clicks and game sounds.
  final AudioPlayer _fx = AudioPlayer(playerId: 'ff_fx')
    ..setPlayerMode(PlayerMode.lowLatency)
    ..setReleaseMode(ReleaseMode.stop);

  @override
  Future<void> play(FfSound sound) async {
    final player = sound == FfSound.alarm ? _alarm : _cues;
    try {
      await player.stop();
      await player.play(AssetSource(sound.asset));
    } on Object {
      // A cue that will not play is not worth an error dialog — most often a
      // browser that has not seen a tap yet. The app is silent for a moment
      // and carries on.
    }
  }

  @override
  Future<void> stopAlarm() async {
    try {
      await _alarm.stop();
    } on Object {
      // Nothing was playing, or the platform already tore it down.
    }
  }

  @override
  Future<void> playWave(Uint8List wav) async {
    try {
      await _buzzer.stop();
      await _buzzer.play(BytesSource(wav, mimeType: 'audio/wav'));
    } on Object {
      // Same as a cue: silence for a moment is better than an error.
    }
  }

  @override
  Future<void> stopWave() async {
    try {
      await _buzzer.stop();
    } on Object {
      // Nothing was playing.
    }
  }

  @override
  Future<void> playFx(Uint8List wav) async {
    try {
      await _fx.stop();
      await _fx.play(BytesSource(wav, mimeType: 'audio/wav'));
    } on Object {
      // A lost click is not worth anything.
    }
  }

  @override
  Future<void> playAlarmWave(Uint8List wav) async {
    try {
      await _alarm.stop();
      await _alarm.play(BytesSource(wav, mimeType: 'audio/wav'));
    } on Object {
      // Same as a cue.
    }
  }

  @override
  Future<void> dispose() async {
    await _cues.dispose();
    await _alarm.dispose();
    await _buzzer.dispose();
    await _fx.dispose();
  }
}

/// Silence. Used by tests, and anywhere playback is not available.
class SilentSoundOutput implements SoundOutput {
  SilentSoundOutput();

  /// What would have been heard, in order.
  final List<FfSound> played = <FfSound>[];

  @override
  Future<void> play(FfSound sound) async => played.add(sound);

  @override
  Future<void> stopAlarm() async {}

  /// Buzzer waves played, in order.
  final List<Uint8List> waves = <Uint8List>[];

  @override
  Future<void> playWave(Uint8List wav) async => waves.add(wav);

  @override
  Future<void> stopWave() async {}

  /// Effects and alarm tones played, in order.
  final List<Uint8List> effects = <Uint8List>[];
  final List<Uint8List> alarmWaves = <Uint8List>[];

  @override
  Future<void> playFx(Uint8List wav) async => effects.add(wav);

  @override
  Future<void> playAlarmWave(Uint8List wav) async => alarmWaves.add(wav);

  @override
  Future<void> dispose() async {}
}
